SYNONYMS = {'восторг': 'благоговение', 'трепет': 'благоговение', 'неуверенность': 'сомнение', 'решимость': 'решимость', 'ужас': 'страх',
            'тоска': 'одиночество', 'удар': 'нокаут', 'покой': 'расслабление', 'печаль': 'горе', 'драма': 'горе', 'счастье': 'радость',
            'ярость': 'гнев', 'тревога': 'напряжение', 'прозрение': 'откровение'}

def get(emotion):
    if not emotion: return None
    e = emotion.strip().lower(); e = SYNONYMS.get(e, e)
    return EMOTIONS.get(e)
